using System.Text.Json;
using MphRead;
using MphRead.Formats;
using MphRead.Mods;
using MphRead.Mods.CustomWeapons.Packages;
using MphRead.Mods.Network;
using MphRead.Mods.Render;
using MphRead.Mods.Replay;
using MphRead.Sound;
using OpenTK.Mathematics;
using OpenTK.Windowing.Desktop;

// Consumes only a bounded immutable recording exported by the ordinary-client harness.
internal static class CustomReplayContactBundleChecks
{
    private sealed record Fact(ReplayFactKind Kind,uint Frame,uint Tick,byte[] Bytes);
    internal static int Run(string input,string output)
    {
        string cwd=Directory.GetCurrentDirectory();NativeWindow? window=null;DesktopGraphicsSession? graphics=null;
        try
        {
            input=Path.GetFullPath(input);output=Path.GetFullPath(output);Directory.CreateDirectory(output);
            byte[] Read(string name,int cap){using var file=File.OpenRead(Path.Combine(input,name));if(file.Length<=0||file.Length>cap)throw new InvalidDataException("Bounded bundle input: "+name);byte[] bytes=new byte[(int)file.Length];file.ReadExactly(bytes);return bytes;}
            string data=File.ReadAllText(Path.Combine(input,"replay-fixture-data.txt"));Directory.SetCurrentDirectory(data);Paths.UpdatePaths();Paths.ChooseMphPath();MapAudit.ForceEveryone=true;
            byte[] packageBytes=Read("variant.ppweapon",32*1024*1024);var package=WeaponPackage.Parse(packageBytes);if(!ReplayCustomWeaponDescriptor.TryRead(Read("inspection-descriptor.bin",32*1024),out var descriptor))throw new InvalidDataException("Invalid actual descriptor.");var context=descriptor!.Bind(package.Definition);
            var facts=new List<Fact>();long payloadBytes=0;using(var stream=new MemoryStream(Read("accepted-full-stream.bin",65*1024*1024)))using(var reader=new BinaryReader(stream))while(stream.Position<stream.Length){if(facts.Count>=32768||stream.Length-stream.Position<13)throw new InvalidDataException("Bounded accepted stream header.");var kind=(ReplayFactKind)reader.ReadByte();uint frame=reader.ReadUInt32(),tick=reader.ReadUInt32();int length=reader.ReadInt32();if(length<=0||length>16384||(payloadBytes+=length)>64*1024*1024||length>stream.Length-stream.Position)throw new InvalidDataException("Bounded accepted payload.");if(kind is not (ReplayFactKind.Match or ReplayFactKind.Roster or ReplayFactKind.Snapshot or ReplayFactKind.Intent or ReplayFactKind.AuthorityWorld or ReplayFactKind.Presentation or ReplayFactKind.CustomWeapon or ReplayFactKind.Event))throw new InvalidDataException("Unexpected accepted lane.");facts.Add(new(kind,frame,tick,reader.ReadBytes(length)));}
            string receipt=File.Exists(Path.Combine(input,"accepted-stream-results.json"))?"accepted-stream-results.json":"contact-results.json";using var receiptJson=JsonDocument.Parse(Read(receipt,1024*1024));int frozen=receiptJson.RootElement.GetProperty("frozenMatchIndex").GetInt32();if(frozen<0||frozen>=facts.Count)throw new InvalidDataException("Missing frozen match index.");int scope=-1;for(int i=0;i<=frozen;i++){var item=facts[i];if(item.Bytes.Length==1+MatchStatePacket.Size&&item.Bytes[0]==(byte)PacketType.MatchState){var match=MatchStatePacket.Read(item.Bytes.AsSpan(1));if(match.MatchId==context.Bootstrap.World.Start.MatchId&&match.AuthorityEpoch==context.Bootstrap.World.Start.AuthorityEpoch&&match.RoomKey==descriptor.Map.RoomKey){scope=i;break;}}}if(scope<0)throw new InvalidDataException("Actual match scope absent.");
            facts=facts.Skip(scope).Where(item=>item.Bytes[0]!=(byte)PacketType.SessionState||SessionStatePacket.TryRead(item.Bytes.AsSpan(1),out var config,allowRetiredEnhanced:true)&&config.MatchId==context.Bootstrap.World.Start.MatchId&&config.AuthorityEpoch==context.Bootstrap.World.Start.AuthorityEpoch&&config.StartGeneration==context.Bootstrap.World.Start.StartGeneration).ToList();for(int i=1;i<facts.Count;i++)if(facts[i].Frame<facts[i-1].Frame)throw new InvalidDataException("Recording frames regress.");
            ReplayTimelineRecord Record(Fact item){if(item.Kind!=ReplayFactKind.Event)return new(item.Frame,item.Tick,item.Kind,item.Bytes);var marker=ReplayTimelineArchive.DecodeMarker(item.Frame,item.Bytes);if(marker.ServerTick!=item.Tick){marker.Release();throw new InvalidDataException("Marker tick differs from accepted callback.");}return marker;}
            void Accept(ReplayReplicaState state,Fact item){if(item.Kind==ReplayFactKind.Event){var marker=Record(item);marker.Release();}else state.Accept(item.Bytes,item.Frame);}
            int checks=0;void Check(bool ok,string label){if(!ok)throw new InvalidDataException(label);checks++;}
            var owner=new ReplayReplicaState();owner.EnableCustomInspection(descriptor);ReplayReplicaCheckpoint? initial=null;var contacts=new List<(uint Frame,MphRead.Mods.CustomWeapons.CustomContactOutcome Outcome)>();var groups=facts.GroupBy(item=>item.Frame).ToArray();var targets=new Dictionary<string,uint>();ushort victimLife=0;int victimSlot=-1;
            foreach(var group in groups){foreach(var item in group){if(initial==null)Accept(owner,item);if(item.Bytes[0]==ReplayCustomWeaponFact.Tag&&ReplayCustomWeaponFact.TryRead(item.Bytes,context,out var fact)&&fact!.TryContact(context,out _,out var contact))contacts.Add((item.Frame,contact));}if(initial==null&&owner.HasRecordedSceneBaseline&&owner.CustomWeapons is{CompleteForRestore:true})initial=owner.CaptureCheckpoint();}
            Check(initial!=null&&contacts.Count>0,"actual native baseline and accepted contacts required");var body=contacts.First(item=>!item.Outcome.Contact.Headshot);var head=contacts.First(item=>item.Outcome.Contact.Headshot&&!item.Outcome.Lethal);var lethal=contacts.First(item=>item.Outcome.Contact.Headshot&&item.Outcome.Lethal);victimSlot=lethal.Outcome.Contact.Key.Victim.Slot;victimLife=lethal.Outcome.Contact.Key.Victim.Life;uint Frame(ReplayReplicaCheckpoint cp){var state=new ReplayReplicaState();state.RestoreCustomCheckpoint(cp);return state.RecordingFrame;}uint origin=Frame(initial!);targets["baseline"]=origin;if(body.Frame>origin)targets["before-body"]=body.Frame-1;var nextLifeContact=contacts.FirstOrDefault(item=>item.Outcome.Contact.Key.Victim.Life!=victimLife&&item.Frame>lethal.Frame);Check(nextLifeContact.Outcome!=default,"actual stream includes new-life accepted contact");targets["end"]=groups[^1].Key;
            var requested=new Dictionary<string,(uint Frame,MphRead.Mods.CustomWeapons.CustomContactOutcome Outcome)>{{"body",body},{"nonlethal-head",head},{"lethal-head",lethal},{"newlife-contact",nextLifeContact}};
            var settings=DesktopGlContext.Settings(background:true);settings.ClientSize=new(960,720);settings.StartVisible=true;settings.Title="Recorded contact bundle reconstruction";window=new NativeWindow(settings);graphics=new DesktopGraphicsSession(window);
            var store=new WeaponPackageStore(Path.Combine(output,"replay-store"));store.Install(packageBytes);using var prepared=Task.Run(()=>PreparedReplayWeaponPackage.Prepare(descriptor,store)).GetAwaiter().GetResult();using var source=PassiveReplayScene.CreateCustomInspection(initial!,prepared,ReplayMapIdentity.Compute(descriptor.Map.RoomKey),new Vector2i(640,480));
            var contactTiming=new List<object>();var captured=new List<(string Name,uint Frame,byte[] World,object[] Actors)>();object[] Actors(PassiveReplayScene scene)=>scene.Scene.Players.Items.Where(player=>player!=null).Select(player=>{var hit=scene.Scene.ModHeadHitPose(player);var death=scene.Scene.ModHeadDeathPose(player,player.ModCorpseDeathDefinition);scene.State.CustomWeapons!.TrySlot(player.SlotIndex,out var custom);var occupant=scene.State.Occupant(player.SlotIndex);scene.State.TryGetPlayer(player.SlotIndex,out var native);return (object)new{slot=player.SlotIndex,player.Health,occupant,native.SlotGeneration,native.LifeId,native.DamageEventId,native.Points,native.Kills,native.Deaths,life=custom.Life,nativeLifeMatches=custom.Life!=0&&scene.State.MatchesLife(player.SlotIndex,occupant.Generation,custom.Life),hitAmount=hit.Amount,hitDirection=new[]{hit.Direction.X,hit.Direction.Y,hit.Direction.Z},death.Active,death.Head,death.Collapse,death.Alpha,death.Side,deathDirection=new[]{death.Direction.X,death.Direction.Y,death.Direction.Z}};}).ToArray();
            void Save(string name){using var world=ReplayWorldCheckpoint.CaptureCustom(source);string filename="file-expected-"+name+"-world12.bin";File.WriteAllBytes(Path.Combine(output,filename),world.Bytes.ToArray());captured.Add((name,source.Session.RecordingFrame,world.Bytes.ToArray(),Actors(source)));}
            Save("baseline");using(var first=ReplayWorldCheckpoint.CaptureCustom(source))using(var writer=new ReplayWriterV3(Path.Combine(output,"actual-full-custom"+DemoFile.Extension),first.ClipMetadata(0,Array.Empty<ReplayPlayerInfo>())))
            {
                for(ulong step=(ulong)origin+1;step<=groups[^1].Key;step++){uint frame=(uint)step;var records=facts.Where(item=>item.Frame==frame).Select(item=>Record(item)).ToArray();try{foreach(var record in records)ReplayTimelineArchive.Write(writer,record,origin);source.StepCustomInspection(frame,records);}finally{foreach(var record in records)record.Release();}foreach(var request in requested){if(targets.ContainsKey(request.Key)||frame<request.Value.Frame)continue;var accepted=request.Value.Outcome;var key=accepted.Contact.Key.Victim;if(source.State.TryGetPlayer(key.Slot,out var native)&&native.SlotGeneration==key.Generation&&native.LifeId==key.Life&&native.Health==accepted.Health.BodyAfter&&native.DamageEventId==accepted.Health.DamageEventId){uint offset=request.Key=="nonlethal-head"?4u:request.Key=="lethal-head"?12u:0u;uint capture=checked(frame+offset);Check(capture<=groups[^1].Key,"genuine reaction sample remains inside accepted stream");targets[request.Key]=capture;contactTiming.Add(new{name=request.Key,contactFrame=request.Value.Frame,nativeMatchFrame=frame,captureFrame=capture,accepted.AuthorityFrame,accepted.Health.DamageEventId});}}
                if(!targets.ContainsKey("respawn")&&frame>lethal.Frame&&source.State.CustomWeapons!.TrySlot(victimSlot,out var victim)&&victim.Life!=0&&victim.Life!=victimLife)targets["respawn"]=frame;
                foreach(var name in targets.Where(pair=>pair.Value==frame&&pair.Key!="baseline").Select(pair=>pair.Key))Save(name);if(targets.Values.Contains(frame)){using var checkpoint=ReplayWorldCheckpoint.CaptureCustom(source);writer.WriteCheckpoint(frame-origin,checkpoint.Bytes);}}
                writer.WriteRecord(groups[^1].Key-origin,new byte[]{255});
            }
            Check(requested.Keys.All(targets.ContainsKey)&&targets.ContainsKey("respawn")&&targets.Count<=8,"all genuine native health/life/event-matched targets captured within budget");
            File.WriteAllBytes(Path.Combine(output,"variant.ppweapon"),packageBytes);File.WriteAllText(Path.Combine(output,"replay-fixture-data.txt"),data);File.WriteAllText(Path.Combine(output,"file-expected-worlds.json"),JsonSerializer.Serialize(captured.Select(item=>new{name=item.Name,frame=item.Frame,filename="file-expected-"+item.Name+"-world12.bin"})));File.WriteAllText(Path.Combine(output,"actor-evidence.json"),JsonSerializer.Serialize(captured.Select(item=>new{item.Name,item.Frame,item.Actors}),new JsonSerializerOptions{IncludeFields=true,WriteIndented=true}));
            File.WriteAllText(Path.Combine(output,"contact-target-timing.json"),JsonSerializer.Serialize(contactTiming,new JsonSerializerOptions{WriteIndented=true}));
            void CompareWorld(string label,ReplayWorldCheckpoint expected,ReplayWorldCheckpoint actual){var differences=expected.CanonicalGraphDifferences(actual);File.WriteAllText(Path.Combine(output,label+"-differences.json"),JsonSerializer.Serialize(differences,new JsonSerializerOptions{WriteIndented=true}));if(differences.Length!=0){File.WriteAllBytes(Path.Combine(output,label+"-expected-world12.bin"),expected.Bytes.ToArray());File.WriteAllBytes(Path.Combine(output,label+"-actual-world12.bin"),actual.Bytes.ToArray());}Check(differences.Length==0,"strict genuine world parity "+label);}
            bool CompareActors(string label,object[] expected,object[] actual){var options=new JsonSerializerOptions{IncludeFields=true,WriteIndented=true};string expectedJson=JsonSerializer.Serialize(expected,options),actualJson=JsonSerializer.Serialize(actual,options);File.WriteAllText(Path.Combine(output,label+"-expected-actors.json"),expectedJson);File.WriteAllText(Path.Combine(output,label+"-actual-actors.json"),actualJson);return actualJson==expectedJson;}
            foreach(var saved in captured.AsEnumerable().Reverse())
            {
                using var world=ReplayWorldCheckpoint.FromCustomBytes(saved.World);using var restored=PassiveReplayScene.RestoreCustomInspection(world,prepared,new Vector2i(640,480));using var actual=ReplayWorldCheckpoint.CaptureCustom(restored);bool actorsMatch=CompareActors("restore-"+saved.Name,saved.Actors,Actors(restored));CompareWorld("restore-"+saved.Name,world,actual);Check(actorsMatch,"explicit immediate actor parity "+saved.Name);
                if(saved.Name is "nonlethal-head" or "lethal-head")
                {
                    var victim=restored.Scene.Players.Items[victimSlot];var hit=restored.Scene.ModHeadHitPose(victim);var death=restored.Scene.ModHeadDeathPose(victim,victim.ModCorpseDeathDefinition);
                    if(saved.Name=="nonlethal-head")Check(hit.Amount>0,"genuine nonlethal head reaction has positive recorded-age pose");else Check(death.Active&&death.Collapse>0,"genuine lethal head reaction has active recorded-age collapse");
                    using var picture=PassiveReplayScene.RestoreCustomInspection(world,prepared,new Vector2i(640,480));var pictureVictim=picture.Scene.Players.Items[victimSlot];var aim=pictureVictim.Position+new Vector3(0,.8f,0);picture.Scene.SetReplicaCamera(aim+new Vector3(2.7f,1.2f,3.8f),aim,55);picture.Scene.OnResize();picture.Scene.OnDrawFrame();Check(picture.Scene.OnRenderFrame(),"fresh genuine contact picture renders "+saved.Name);Check(ScreenCapture.SaveWindow(picture.Scene,Path.Combine(output,saved.Name+"-window.png"))&&ScreenCapture.Save(picture.Scene,Path.Combine(output,saved.Name+"-world.png")),"genuine contact victim window/world images retained "+saved.Name);DesktopGraphicsSession.Present(window);picture.Scene.AfterRenderFrame();
                }
                for(ulong step=(ulong)saved.Frame+1;step<=groups[^1].Key;step++){uint frame=(uint)step;var records=facts.Where(item=>item.Frame==frame).Select(item=>Record(item)).ToArray();try{restored.StepCustomInspection(frame,records);}finally{foreach(var record in records)record.Release();}foreach(var expected in captured.Where(item=>item.Frame==frame)){using var expectedWorld=ReplayWorldCheckpoint.FromCustomBytes(expected.World);using var current=ReplayWorldCheckpoint.CaptureCustom(restored);bool suffixActorsMatch=CompareActors("suffix-"+saved.Name+"-to-"+expected.Name,expected.Actors,Actors(restored));CompareWorld("suffix-"+saved.Name+"-to-"+expected.Name,expectedWorld,current);Check(suffixActorsMatch,"explicit suffix actor parity "+expected.Name);}}
            }
            Check(CustomReplayFileReopenChecks.Validate(output,Path.Combine(output,"file-reopen"),window)>0,"full contact archive cold file seek and suffix validation");File.WriteAllText(Path.Combine(output,"contact-bundle-results.json"),JsonSerializer.Serialize(new{checks,records=facts.Count,contacts=contacts.Count,targets=targets,contactTiming,scope="Actual supplied ordinary-client facts reconstructed in loaded private Scenes, strict world and explicit native health/life/contact pose parity. No fabricated contact, HP, freeze/form eligibility or authority claims."}));Console.WriteLine($"PASS {checks} genuine contact bundle reconstruction checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CONTACT BUNDLE FAIL "+error);return 1;}
        finally{AudioLifetime.Shutdown();graphics?.Dispose();window?.Dispose();Directory.SetCurrentDirectory(cwd);}
    }
}
